typedef unsigned int u_int;

enum WaveRegionEnum
{
  WAVE_REGIONCURL = 2,
  WAVE_REGIONROOF = 7,
  WAVE_REGIONSHOULDER = 8,
  WAVE_REGIONSHOULDER2 = 13
};

struct surface_point_t
{
  char data[0x23c];
  WaveRegionEnum region;
  u_int vvalid;
};

struct trail_node_t
{
  u_int valid;
  float age;
  float uv;
  surface_point_t pnt1;
  surface_point_t pnt2;
  surface_point_t pnt3;
};

struct spray_control_t
{
  char data[0x60];
};
struct spray_params_t
{
  spray_control_t control_points_a[25];
  spray_control_t control_points_b[25];
};

class SurfBoardObjectClass
{
public:
  bool InAir();
};

class kellyslater_controller
{
public:
  bool is_active();
  SurfBoardObjectClass &get_board_controller();
};

class trail
{
public:
  virtual ~trail();
  void update(float dt);
  void update_surface_point(surface_point_t *sp);
  void spraypt_update(spray_control_t *points, u_int max);
  void board_update_air(float dt);
  void board_update(float dt);

private:
  bool valid;
  u_int my_index;
  float my_life;
  float my_sample_rate;
  float my_last_sample;
  u_int my_total_nodes;
  trail_node_t my_trail_data[30];
  bool my_extra;
  float my_lastmag1;
  float my_lastmag2;
  kellyslater_controller *my_owner;
  spray_params_t *my_spray;
};

void trail::update (float dt)
{
  WaveRegionEnum region;

  if (my_owner && !my_owner->is_active())
    return;

  my_last_sample += dt;

  for (u_int i = 0; i < my_total_nodes; i++)
  {
    trail_node_t *node = &my_trail_data[i];

    if (!node->valid)
      continue;

    node->age += dt;

    if (node->age > my_life)
    {
      node->valid = false;
      continue;
    }

    update_surface_point (&node->pnt1);
    region = node->pnt1.region;

    if ((region == WAVE_REGIONROOF) || (region == WAVE_REGIONCURL) ||
        (region == WAVE_REGIONSHOULDER) || (region == WAVE_REGIONSHOULDER2))
    {
      node->age *= 1.75f;
      continue;
    }

    if (my_extra)
    {
      update_surface_point (&node->pnt2);
      region = node->pnt2.region;

      if ((region == WAVE_REGIONROOF) || (region == WAVE_REGIONCURL) ||
          (region == WAVE_REGIONSHOULDER) || (region == WAVE_REGIONSHOULDER2))
      {
        node->age *= 1.75f;
        continue;
      }
    }

    update_surface_point (&node->pnt3);
    region = node->pnt3.region;

    if ((region == WAVE_REGIONROOF) || (region == WAVE_REGIONCURL) ||
        (region == WAVE_REGIONSHOULDER) || (region == WAVE_REGIONSHOULDER2))
    {
      node->age *= 1.75f;
      continue;
    }
  }

  if (my_owner)
  {
    SurfBoardObjectClass& board = my_owner->get_board_controller();

    spraypt_update (my_spray->control_points_a, 25);
    spraypt_update (my_spray->control_points_b, 25);

    if (board.InAir ())
      board_update_air (dt);
    else
      board_update (dt);
  }
}
